"use client";
import { useEffect, useState } from "react";
import { EosDesignPage } from "@/components/application/eos/design-page";
import { eosLook } from "@/components/application/eos/tokens";

/** Morrow in all three views, with the look switcher in its bar. `variant` picks the look it starts in. */
export default function EosDesignPageDemo({ variant }: { variant?: string }) {
  const [look, setLook] = useState(() => eosLook(variant));
  // A look chosen outside the page (the element page's picker) moves the switcher too.
  useEffect(() => setLook(eosLook(variant)), [variant]);
  return <EosDesignPage look={look} onLookChange={setLook} />;
}

