"use client";
/**
 * EosDesignPage: the Eos theme as one product's page, in any of its five looks. Morrow, a fictional app that runs
 * routines while you sleep, is shown in three views: Discover, the Connect Coffer page and the app on its Routines
 * page. A segmented control in the page's bar switches the look in place: the page and its views stay mounted, focus
 * stays on the control and the reader keeps their place: the heading in view (or else the section under the bar)
 * stays where it was on screen. Where motion is allowed the new look fades in over the old one (motion.ts); with
 * reduced motion it swaps at once. Every word comes from `content`; pass any part of it to change the copy.
 *
 * What differs between looks is tokens (tokens.ts) and the few layout choices each look names there: the side rail,
 * the card media, the Discover grid, the connect page's layout and how the app sits on the page.
 *
 * Inspired by rico (@_heyrico)'s twin visual vibe.
 */
import { useId, useRef, useState, type CSSProperties } from "react";
import { flushSync } from "react-dom";
import { EosAppShell, EosAppSidebar } from "./app-shell";
import { EOS_MORROW, type EosDesignContent } from "./design/content";
import { EosBentoTiles, EosCategoryIndex, EosDiscover, eosRoutinesContent } from "./design/views";
import { EosDetailHeader } from "./detail-header";
import { EosMark } from "./glyphs";
import { EosGradientBanner } from "./gradient-banner";
import { eosCrossfade, useEosFollow, useEosLoop } from "./motion";
import { EosRoutinesPage } from "./routines-app";
import { EosSegmentedControl, type EosSegment } from "./segmented-control";
import { cx, useControlled, useMedia } from "./shared";
import { EosTheme } from "./theme";
import { EOS_LOOK_SPECS, EOS_LOOKS, eosLook, type EosLook, type EosMode } from "./tokens";

const CSS = `
.eos-dp{position:relative;isolation:isolate;min-height:100vh;overflow-anchor:none;--eos-dp-bar:64px;--eos-dp-pad:clamp(16px,4.4vw,64px);--eos-dp-top:clamp(40px,6vw,88px);--eos-dp-bottom:clamp(72px,10vw,144px)}
.eos-dp[data-eos-look=night]{--eos-dp-pad:clamp(16px,4vw,48px);--eos-dp-top:clamp(28px,4vw,56px)}
.eos-dp[data-eos-look=editorial]{--eos-dp-top:clamp(32px,4.4vw,64px)}
.eos-dp[data-eos-look=bold]{--eos-dp-pad:clamp(10px,2.4vw,32px);--eos-dp-top:clamp(10px,1.4vw,18px);--eos-dp-bottom:clamp(40px,6vw,96px)}
.eos-dp-field{position:fixed;inset:0;z-index:-1;overflow:hidden;pointer-events:none;background:var(--eos-backdrop),var(--eos-canvas)}
.eos-dp-field span{position:absolute;border-radius:50%;filter:blur(60px)}
.eos-dp-drift{position:absolute;inset:0}
.eos-dp-field [data-petal=a]{width:62vw;height:62vw;left:-22vw;top:-18vw;opacity:.9;background:var(--eos-dp-glow)}
.eos-dp-field [data-petal=b]{width:30vw;height:110vw;right:-6vw;top:32%;transform:rotate(28deg);opacity:.7;background:var(--eos-dp-glow)}
.eos-dp-field [data-petal=c]{width:70vw;height:50vw;left:10vw;bottom:-14vw;opacity:.55;background:var(--eos-glow-blush)}
.eos-dp-field .eos-dp-grain{inset:0;border-radius:0;filter:none;background-image:var(--eos-grain);background-size:200px 200px;mix-blend-mode:overlay;opacity:var(--eos-grain-opacity)}
.eos-dp-bar{position:sticky;top:0;z-index:30;display:flex;align-items:center;gap:16px;box-sizing:border-box;height:var(--eos-dp-bar);padding:0 clamp(12px,3vw,32px);background:var(--eos-bar);border-bottom:1px solid var(--eos-hairline);-webkit-backdrop-filter:blur(18px) saturate(1.4);backdrop-filter:blur(18px) saturate(1.4)}
.eos-dp-brand{display:flex;align-items:center;gap:10px;margin:0;font-family:var(--eos-font-display);font-size:22px;font-weight:var(--eos-display-weight);letter-spacing:-.015em;color:var(--eos-text);white-space:nowrap}
.eos-dp-switch{display:flex;align-items:center;gap:12px;min-width:0;margin-left:auto}
.eos-dp-switch-label{font-size:14px;color:var(--eos-text-secondary)}
.eos-dp-body{display:grid;grid-template-columns:minmax(0,1fr);align-items:start}
.eos-dp-body[data-rail=index]{grid-template-columns:clamp(196px,16vw,240px) minmax(0,1fr);column-gap:clamp(24px,3vw,56px);padding-left:clamp(16px,4vw,56px)}
.eos-dp-body[data-rail=app]{grid-template-columns:272px minmax(0,1fr)}
.eos-dp-rail{position:sticky;top:var(--eos-dp-bar);box-sizing:border-box;min-width:0}
.eos-dp-body[data-rail=index] .eos-dp-rail{padding-top:var(--eos-dp-top)}
.eos-dp-body[data-rail=app] .eos-dp-rail{height:calc(100vh - var(--eos-dp-bar));background:var(--eos-sidebar);border-right:1px solid var(--eos-hairline)}
.eos-dp-body[data-rail=app] .eos-side-inner{width:100%;height:100%;max-height:none}
.eos-dp-main{display:grid;grid-template-columns:minmax(0,1fr);gap:var(--eos-section-gap);box-sizing:border-box;width:100%;min-width:0;max-width:calc(var(--eos-page-width) + 2 * var(--eos-dp-pad));margin:0 auto;padding:var(--eos-dp-top) var(--eos-dp-pad) var(--eos-dp-bottom)}
.eos-dp-main>.eos-detail[data-layout=card]{justify-self:center;width:100%;max-width:880px}
.eos-dp-h{margin:0;font-family:var(--eos-font-display);font-weight:var(--eos-display-weight);font-size:clamp(30px,5vw,var(--eos-heading-size));line-height:1.04;letter-spacing:var(--eos-display-tracking);color:var(--eos-page-text);text-wrap:balance}
.eos-dp-lede{margin:12px 0 0;max-width:46ch;font-size:clamp(16px,1.5vw,18px);line-height:1.55;color:var(--eos-page-text-soft)}
.eos-dp-apphead{margin:0 0 clamp(24px,3vw,40px)}
[data-eos-look=editorial] .eos-dp-h{max-width:11ch;font-size:clamp(46px,7vw,var(--eos-heading-size));line-height:.98}
[data-eos-look=editorial] .eos-dp-lede{margin-top:22px;max-width:44ch;font-size:clamp(17px,1.6vw,20px)}
[data-eos-look=editorial] .eos-dp-apphead{margin-bottom:48px}
.eos-dp-frame{width:100%}
.eos-dp-frame>.eos-banner-body{display:block;width:100%;padding:0}
.eos-dp-app[data-app=field] .eos-dp-frame{padding:clamp(14px,4.4vw,64px)}
.eos-dp-app[data-app=field] .eos-dp-window{border-radius:20px;border:1px solid rgba(255,255,255,.08);box-shadow:var(--eos-float-shadow)}
.eos-dp-app[data-app=frame] .eos-dp-frame{padding:clamp(12px,4vw,56px);background:var(--eos-well);border:1px solid var(--eos-hairline)}
.eos-dp-app[data-app=frame] .eos-dp-frame::before{content:"";position:absolute;z-index:1;left:24px;right:24px;top:22px;height:5px;border-radius:999px;background:var(--eos-gradient-orchid)}
.eos-dp-app[data-app=frame] .eos-dp-window{border-radius:18px;box-shadow:var(--eos-float-shadow)}
.eos-dp-app[data-app=float] .eos-dp-frame{max-width:1180px;margin:0 auto;background:none;overflow:visible}
.eos-dp-app[data-app=float] .eos-dp-window{border-radius:22px;border:1px solid rgba(255,255,255,.14);box-shadow:0 40px 90px -40px rgba(20,14,70,.65)}
.eos-dp-app[data-app=tile]{padding:clamp(20px,3vw,40px);border-radius:var(--eos-radius-card);background:var(--eos-card);border:1px solid var(--eos-hairline)}
.eos-dp-app[data-app=tile] .eos-dp-h{color:var(--eos-text)}
.eos-dp-app[data-app=tile] .eos-dp-lede{color:var(--eos-text-secondary)}
.eos-dp-app[data-app=tile] .eos-dp-frame{background:none;border-radius:calc(var(--eos-radius-card) - 8px)}
.eos-dp-app[data-app=page]{padding-top:clamp(40px,6vw,72px);border-top:1px solid var(--eos-hairline)}
.eos-dp-app[data-app=page] .eos-dp-apphead{display:none}
.eos-dp-app[data-app=page] .eos-dp-frame{background:none;border-radius:0;overflow:visible}
.eos-dp-app[data-app=page] .eos-routines{padding:0;max-width:860px}
@media (max-width:900px){
  .eos-dp-body[data-rail]{grid-template-columns:minmax(0,1fr);column-gap:0;padding-left:0}
  .eos-dp-body[data-rail=app] .eos-dp-rail{display:none}
  .eos-dp-body[data-rail=index] .eos-dp-rail{position:static;padding:var(--eos-dp-top) var(--eos-dp-pad) 0}
  .eos-dp-body[data-rail=index] .eos-dp-main{padding-top:36px}
}
@media (max-width:640px){
  .eos-dp-bar{gap:0;padding:0 8px}
  .eos-dp-brand,.eos-dp-switch-label{display:none}
  .eos-dp-switch{flex:1}
  .eos-dp-switch .eos-seg{width:100%}
  .eos-dp-switch .eos-seg-option{padding:0 6px;font-size:13.5px}
}
`;

/** The switcher's segments: every look, by its title. */
export const EOS_LOOK_SEGMENTS: readonly EosSegment[] = EOS_LOOKS.map((look) => ({ value: look, label: EOS_LOOK_SPECS[look].title }));

/**
 * The reader's place, and where on screen it is: the heading of the first page section whose heading shows in full
 * below the bar, or else the first section still showing below the bar. None at the top of the page, which stays the
 * top.
 */
interface Place {
  node: Element;
  top: number;
}

function placeOf(main: HTMLElement | null, bar: HTMLElement | null): Place | null {
  if (!main || window.scrollY <= 0) return null;
  const line = bar?.getBoundingClientRect().bottom ?? 0;
  const sections = [...main.children].filter((child) => child.tagName === "SECTION");
  for (const section of sections) {
    const label = section.getAttribute("aria-labelledby");
    const heading = label ? (section.getRootNode() as Document | ShadowRoot).getElementById(label) : null;
    const box = heading?.getBoundingClientRect();
    if (heading && box && box.height > 0 && box.top >= line && box.bottom <= window.innerHeight) return { node: heading, top: box.top };
  }
  for (const section of sections) {
    const box = section.getBoundingClientRect();
    if (box.bottom > line) return { node: section, top: box.top };
  }
  return null;
}

/** Scroll by however far the reader's place moved in the new look, so it is where it was on screen. */
function keepPlace(place: Place | null) {
  if (!place) return;
  const moved = place.node.getBoundingClientRect().top - place.top;
  if (Math.abs(moved) >= 1) window.scrollBy(0, moved);
}

export interface EosDesignPageProps {
  /** The look, when the page around it holds the choice; pair it with onLookChange so the switcher can change it. */
  look?: EosLook;
  /** The look to start in when the page holds the choice itself. */
  defaultLook?: EosLook;
  onLookChange?: (look: EosLook) => void;
  /** Light or dark. By default each look's own: night is dark, the others light. */
  mode?: EosMode;
  /** The look switcher in the page's bar. */
  switcher?: boolean;
  /** Any part of the copy, over the Morrow defaults. */
  content?: Partial<EosDesignContent>;
  className?: string;
  style?: CSSProperties;
}

export function EosDesignPage({
  look,
  defaultLook = "pastel",
  onLookChange,
  mode,
  switcher = true,
  content,
  className,
  style,
}: EosDesignPageProps) {
  const [chosen, setChosen] = useControlled<EosLook>(look === undefined ? undefined : eosLook(look), eosLook(defaultLook), onLookChange);
  const current = eosLook(chosen);
  const spec = EOS_LOOK_SPECS[current];
  const { rail, detail } = spec.layout;
  const tone: EosMode = mode ?? spec.mode;
  const c: EosDesignContent = { ...EOS_MORROW, ...content };
  const [filter, setFilter] = useState("all");
  // The night look's page is the app, with its sidebar as the page's rail; on a narrow screen the app keeps its own.
  const wide = useMedia("(min-width: 901px)", true);
  const app = spec.layout.app === "page" && !wide ? "tile" : spec.layout.app;
  const bar = useRef<HTMLElement>(null);
  const main = useRef<HTMLElement>(null);
  const field = useRef<HTMLDivElement>(null);
  const id = useId();
  // The backdrop's glows drift slowly over its gradient while it shows; the grain holds still on top.
  useEosLoop(field, Boolean(spec.backdrop));
  // When a filter changes how many cards Discover holds, what follows it slides to its new place.
  const follow = useEosFollow(
    () => {
      const sections = main.current ? ([...main.current.children] as HTMLElement[]) : [];
      const at = sections.findIndex((el) => el.classList.contains("eos-discover"));
      return at < 0 ? [] : sections.slice(at + 1);
    },
    filter,
    current,
  );
  const filterTo = (next: string) => {
    if (next === filter) return;
    follow();
    setFilter(next);
  };

  const choose = (value: string) => {
    const next = eosLook(value);
    if (next === current) return;
    const place = placeOf(main.current, bar.current);
    eosCrossfade(() => {
      flushSync(() => setChosen(next));
      keepPlace(place);
    }, next);
  };

  return (
    <EosTheme look={current} mode={tone} className={cx("eos-dp", className)} style={style}>
      <style>{CSS}</style>
      {spec.backdrop && (
        <div ref={field} className="eos-dp-field" style={{ "--eos-dp-glow": `var(--eos-glow-${spec.backdrop})` } as CSSProperties} aria-hidden>
          <div className="eos-dp-drift eos-drift">
            <span data-petal="a" />
            <span data-petal="b" />
            <span data-petal="c" />
          </div>
          <span className="eos-dp-grain" />
        </div>
      )}
      <header ref={bar} className="eos-dp-bar">
        <p className="eos-dp-brand">
          <EosMark kind="sun" size={24} />
          {c.product}
        </p>
        {switcher && (
          <div className="eos-dp-switch">
            <span className="eos-dp-switch-label" aria-hidden>
              Look
            </span>
            <EosSegmentedControl segments={EOS_LOOK_SEGMENTS} value={current} onChange={choose} label="Look" size="sm" />
          </div>
        )}
      </header>
      <div className="eos-dp-body" data-rail={rail ?? "none"}>
        {rail === "index" && (
          <aside className="eos-dp-rail" aria-label="Routine categories">
            <EosCategoryIndex content={c} filter={filter} onFilter={filterTo} />
          </aside>
        )}
        {rail === "app" && (
          <aside className="eos-dp-rail" aria-label={`${c.product} sidebar`}>
            <EosAppSidebar defaultActive="routines" />
          </aside>
        )}
        <main ref={main} className="eos-dp-main">
          <EosDiscover content={c} filter={filter} onFilter={filterTo} headingLevel={1} />
          <EosDetailHeader
            from={c.detail.from}
            to={c.detail.to}
            title={c.detail.title}
            subline={c.detail.subline}
            about={c.detail.about}
            action={{ label: c.detail.action }}
            note={c.detail.note}
            quote={c.detail.quote}
          >
            {detail === "bento" && <EosBentoTiles content={c} />}
          </EosDetailHeader>
          <section className="eos-dp-app" data-app={app} aria-labelledby={`${id}-app`}>
            <div className="eos-dp-apphead">
              <h2 id={`${id}-app`} className="eos-dp-h">
                {c.shell.heading}
              </h2>
              <p className="eos-dp-lede">{c.shell.lede}</p>
            </div>
            <EosGradientBanner className="eos-dp-frame" gradient="dawn" shape="card" height="auto" petals={app === "field"} grain={app === "field"}>
              <EosAppShell
                className="eos-dp-window"
                chrome={app !== "page"}
                height={app === "page" ? "auto" : 740}
                mode={app === "page" ? tone : "dark"}
                title={c.shell.title}
              >
                <EosRoutinesPage content={eosRoutinesContent(c)} headingLevel={3} />
              </EosAppShell>
            </EosGradientBanner>
          </section>
        </main>
      </div>
    </EosTheme>
  );
}
